// Reports: this month's totals from the API, and CSV downloads generated by the server.
import { $ } from "../core/dom.js";
import { api, unwrap } from "../core/api.js";
import { toast } from "../core/toast.js";

const fmt = (v) => (Number.isFinite(Number(v)) ? Number(v).toLocaleString("fa-IR") : "—");
const isoDay = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

// The report period is the current calendar month, from the 1st until today.
function period() {
  const now = new Date();
  const first = new Date(now.getFullYear(), now.getMonth(), 1);
  return { from: isoDay(first), to: isoDay(now) };
}

const REPORTS = [
  { key: "trade-summary", title: "خلاصه خرید و فروش", sub: "مجموع اسناد تأییدشده‌ی این ماه", periodic: true },
  { key: "weighbridge", title: "گزارش باسکول", sub: "تعداد و وزن خالص توزین‌های این ماه", periodic: true },
  { key: "party-balances", title: "مانده‌ی طرف حساب‌ها", sub: "طلب و بدهی باز هر طرف حساب", periodic: false },
  { key: "stock", title: "موجودی انبار", sub: "موجودی فعلی هر ماده", periodic: false },
];

export function reportsMarkup() {
  return `<div class="metric-grid"><article class="metric-card"><div class="metric-top">فروش این ماه <span class="metric-icon icon-emerald">↗</span></div><div class="metric-value" id="rSales">…</div><div class="metric-foot">اسناد تأییدشده</div></article><article class="metric-card"><div class="metric-top">خرید این ماه <span class="metric-icon icon-blue">↙</span></div><div class="metric-value" id="rPurchases">…</div><div class="metric-foot">اسناد تأییدشده</div></article><article class="metric-card"><div class="metric-top">توزین‌های این ماه <span class="metric-icon icon-violet">▤</span></div><div class="metric-value" id="rWeighbridge">…</div><div class="metric-foot">ورودی و خروجی</div></article><article class="metric-card"><div class="metric-top">مطالبات باز <span class="metric-icon icon-amber">◫</span></div><div class="metric-value" id="rReceivable">…</div><div class="metric-foot">از همه‌ی طرف حساب‌ها</div></article></div><article class="panel report-shortcuts"><div class="panel-heading"><div><h2>گزارش‌های آماده</h2><p>هر گزارش را به‌صورت فایل CSV دانلود کنید. گزارش‌های دوره‌ای برای این ماه هستند.</p></div></div><div class="shortcut-grid">${REPORTS.map(
    (r) => `<button class="shortcut" data-report="${r.key}" data-periodic="${r.periodic ? "1" : "0"}"><span>⇩</span><strong>${r.title}</strong><small>${r.sub}</small></button>`,
  ).join("")}</div></article>`;
}

async function download(report, periodic) {
  const { from, to } = period();
  const query = periodic ? `from=${from}&to=${to}&format=csv` : "format=csv";
  const blob = await api(`/reports/${report}?${query}`, { raw: true });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${report}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

async function loadMetrics() {
  const { from, to } = period();
  try {
    const [trade, weighbridge, balances] = await Promise.all([
      api(`/reports/trade-summary?from=${from}&to=${to}`),
      api(`/reports/weighbridge?from=${from}&to=${to}`),
      api("/reports/party-balances").then(unwrap),
    ]);
    $("rSales").textContent = fmt(trade.sales.total_minor);
    $("rPurchases").textContent = fmt(trade.purchases.total_minor);
    $("rWeighbridge").textContent = fmt(weighbridge.inbound.tickets + weighbridge.outbound.tickets);
    $("rReceivable").textContent = fmt(balances.reduce((sum, b) => sum + Number(b.receivable_minor || 0), 0));
  } catch (err) {
    toast(err.message);
  }
}

export function bindReports() {
  loadMetrics();

  document.querySelectorAll("[data-report]").forEach((button) => {
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        await download(button.dataset.report, button.dataset.periodic === "1");
      } catch (err) {
        toast(err.message);
      } finally {
        button.disabled = false;
      }
    });
  });
}
